function aviso(cabeceras, hoy) {
  const dep = cabeceras["deprecation"];
  const sun = cabeceras["sunset"];
  const avisos = [];
  if (dep) {
    const m = dep.match(/^@(\d+)$/); // RFC 9745: fecha como entero, con @ adelante
    const desde = m ? new Date(Number(m[1]) * 1000) : null;
    avisos.push(desde ? `deprecada desde ${desde.toISOString().slice(0, 10)}` : `Deprecation con formato raro: ${dep}`);
  }
  if (sun) {
    const retiro = new Date(sun); // RFC 8594: fecha HTTP
    const dias = Math.ceil((retiro - hoy) / 86400000);
    avisos.push(`se apaga el ${retiro.toISOString().slice(0, 10)} (faltan ${dias} días)`);
  }
  return avisos.length ? avisos.join("; ") : "sin avisos";
}

const hoy = new Date("2026-11-13T12:00:00Z");
console.log(aviso({}, hoy));
console.log(aviso({ deprecation: "@1788220800", sunset: "Mon, 01 Mar 2027 00:00:00 GMT" }, hoy));
console.log(aviso({ deprecation: "true" }, hoy));
